  "source": "def simulate_actions(actions):
    committed_ids = []
    pending_ids = []
    in_transaction = False
    snapshot_committed = None

    for action in actions:
        op = action["op"]
        if op == "put":
            target_id = action["id"]
            if in_transaction:
                pending_ids.append(target_id)
            else:
                committed_ids.append(target_id)
        elif op == "delete":
            target_id = action["id"]
            if in_transaction:
                if target_id in pending_ids:
                    pending_ids.remove(target_id)
                elif target_id in committed_ids:
                    # Mark deletion by removing from a logical view, but we need to track max ever inserted.
                    # Actually, simpler: just maintain the list of currently visible rows? 
                    # No, AUTOINCREMENT depends on history. 
                    # Let's stick to tracking 'max_ever_allocated' separately or deriving it.
                    pass
            else:
                if target_id in committed_ids:
                    committed_ids.remove(target_id)
        elif op == "begin":
            if not in_transaction:
                in_transaction = True
                snapshot_committed = list(committed_ids)
                pending_ids = []
        elif op == "commit":
            if in_transaction:
                committed_ids.extend(pending_ids)
                pending_ids = []
                in_transaction = False
                snapshot_committed = None
        elif op == "rollback":
            if in_transaction:
                committed_ids = snapshot_committed
                pending_ids = []
                in_transaction = False
                snapshot_committed = None

    return committed_ids + pending_ids

def get_max_allocated_id(actions):
    max_id = 0
    in_transaction = False
    temp_max_in_txn = -1

    for action in actions:
        op = action["op"]
        if op == "put":
            current_id = action["id"]
            if in_transaction:
                if current_id > temp_max_in_txn:
                    temp_max_in_txn = current_id
            else:
                if current_id > max_id:
                    max_id = current_id
        elif op == "begin":
            if not in_transaction:
                in_transaction = True
                temp_max_in_txn = -1
        elif op == "commit":
            if in_transaction:
                if temp_max_in_txn > max_id:
                    max_id = temp_max_in_txn
                in_transaction = False
                temp_max_in_txn = -1
        elif op == "rollback":
            if in_transaction:
                in_transaction = False
                temp_max_in_txn = -1

    return max_id

